public class Solution {
    public static CourseSupport.Node<Integer> bstRemove(CourseSupport.Node<Integer> root,int x) {
        if(root==null)return null;
        if(x<root.data)root.left=bstRemove(root.left,x);
        else if(x>root.data)root.right=bstRemove(root.right,x);
        else {
            if(root.left==null)return root.right;
            if(root.right==null)return root.left;
            CourseSupport.Node<Integer> succ=root.right;
            while(succ.left!=null)succ=succ.left;
            root.data=succ.data;
            root.right=bstRemove(root.right,succ.data);
        }
        return root;
    }
}

