public class Solution {
    public static void insertionSort(ArrayDeque<Integer> q) {
        ArrayDeque<Integer> sorted=new ArrayDeque<>();
        while(!q.isEmpty()){
            int x=q.removeFirst();
            ArrayDeque<Integer> t=new ArrayDeque<>();
            while(!sorted.isEmpty()&&sorted.peekFirst()<=x)t.addLast(sorted.removeFirst());
            t.addLast(x);
            t.addAll(sorted);
            sorted=t;
        }
        q.addAll(sorted);
    }
}

