public class Solution {
    public static List<Integer> quickSort(List<Integer> a) {
        if(a.size()<=1)return new ArrayList<>(a);
        int pivot=a.get(0);
        List<Integer> low=new ArrayList<>(),high=new ArrayList<>();
        for(int i=1;i<a.size();i++){int x=a.get(i);if(x<=pivot)low.add(x);else high.add(x);}
        List<Integer> out=quickSort(low);out.add(pivot);out.addAll(quickSort(high));return out;
    }
}

