import java.util.*;

public class Solution {
    public static boolean isHeap(CourseSupport.Node<Integer> root) {
        Queue<CourseSupport.Node<Integer>> q=new LinkedList<>();q.add(root);boolean seenGap=false;
        while(!q.isEmpty()){
         CourseSupport.Node<Integer> node=q.remove();if(node==null){seenGap=true;continue;}
         if(seenGap)return false;
         if(node.left!=null&&node.data>node.left.data)return false;
         if(node.right!=null&&node.data>node.right.data)return false;
         q.add(node.left);q.add(node.right);
        }
        return true;
    }
}

