public class Solution {
    public static Map<Integer,List<String>> rehash(Map<String,Integer> input,int bucketCount) {
        Map<Integer,List<String>> m=new HashMap<>();for(int i=0;i<bucketCount;i++)m.put(i,new ArrayList<>());
